function doViewBetList(n,t,i){var r=age.GetBaseUrl()+"_BetList/BetList.aspx?matchId="+n+"&betType="+t+"&type="+i;window.location.href=r}function doViewBetListRacing(n,t,i){var r=age.GetBaseUrl()+"_BetList/BetList.aspx?matchId="+n+"&betType="+t+"&type="+i+"&racing=1";window.location.href=r}function doViewBetListGame(n,t,i,r){var u=age.GetBaseUrl()+"_BetList/BetList.aspx?matchId="+n+"&betType="+t+"&type="+i+"&islive="+r;window.location.href=u}function doViewBetListNewGames(n,t,i,r,u){var f=age.GetBaseUrl()+"_BetList/BetList.aspx?matchId="+n+"&betType="+t+"&type="+i+"&islive="+r+"&betteam="+u;window.location.href=f}function openForecast(n,t){var i=age.GetExTotalBetsForecastUrl()+"_Forecast/FCAH.aspx?matchId="+n+"&b="+t;top.popupManager.openMultiple(i,900)}function openForecast1X2(n,t){var i=age.GetExTotalBetsForecastUrl()+"_Forecast/FC1X2.aspx?is_popup=1&matchId="+n+"&betType="+t;top.popupManager.openMultiple(i,"",900)}